'use strict';

const path = require('node:path');
const fs = require('node:fs');
const { exec } = require('node:child_process');
const util = require('node:util');
const execAsync = util.promisify(exec);

const SKIP_DIRS = new Set(['node_modules', '.git', 'target', 'dist', 'build']);

function canonical(p) {
  try {
    return fs.realpathSync.native(p);
  } catch {
    return path.resolve(p);
  }
}

function isValidChildDir(entry) {
  return entry.isDirectory() && !entry.name.startsWith('.') && !SKIP_DIRS.has(entry.name);
}

function collectDirectChildren(baseDir, cds) {
  const out = [];
  if (!cds.utils.exists(baseDir)) return out;
  const entries = cds.utils.fs.readdirSync(baseDir, { withFileTypes: true });
  for (const entry of entries) {
    if (!isValidChildDir(entry)) continue;
    const pkg = path.join(baseDir, entry.name, 'package.json');
    if (cds.utils.exists(pkg)) out.push(pkg);
  }
  return out;
}

function collectRecursive(baseDir, cds, out = []) {
  if (!cds.utils.exists(baseDir)) return out;
  const entries = cds.utils.fs.readdirSync(baseDir, { withFileTypes: true });
  for (const entry of entries) {
    if (!isValidChildDir(entry)) continue;
    const sub = path.join(baseDir, entry.name);
    const pkg = path.join(sub, 'package.json');
    if (cds.utils.exists(pkg)) out.push(pkg);
    collectRecursive(sub, cds, out);
  }
  return out;
}

function matchPattern(pattern, cds) {
  if (pattern === '**' || pattern === '**/*') {
    return collectRecursive(cds.root, cds);
  }
  if (pattern === '*') {
    return collectDirectChildren(cds.root, cds);
  }
  if (pattern.endsWith('/**') || pattern.endsWith('/**/*')) {
    const prefix = pattern.replace(/\/\*\*(\/\*)?$/, '');
    return collectRecursive(path.join(cds.root, prefix), cds);
  }
  if (pattern.endsWith('/*')) {
    const prefix = pattern.slice(0, -2);
    return collectDirectChildren(path.join(cds.root, prefix), cds);
  }
  // Direct path.
  const pkg = path.join(cds.root, pattern, 'package.json');
  return cds.utils.exists(pkg) ? [pkg] : [];
}

async function filterGitIgnored(paths, cds) {
  const env = { ...process.env, GIT_CEILING_DIRECTORIES: path.dirname(cds.root) };
  const out = [];
  for (const p of paths) {
    try {
      await execAsync(`git check-ignore -q "${p}"`, { cwd: cds.root, env });
      // exit 0 → ignored, drop
    } catch {
      out.push(p);
    }
  }
  return out;
}

async function collectWorkspacePackageJsons(cds) {
  const rootPkgPath = path.join(cds.root, 'package.json');
  const set = new Map(); // canonical → original
  if (cds.utils.exists(rootPkgPath)) set.set(canonical(rootPkgPath), rootPkgPath);

  let patterns = [];
  if (cds.utils.exists(rootPkgPath)) {
    try {
      const rootPkg = JSON.parse(cds.utils.fs.readFileSync(rootPkgPath, 'utf8'));
      if (rootPkg.workspaces) {
        patterns = Array.isArray(rootPkg.workspaces)
          ? rootPkg.workspaces
          : (rootPkg.workspaces.packages || []);
      }
    } catch { /* fall through */ }
  }

  const matched = [];
  for (const p of patterns) matched.push(...matchPattern(p, cds));

  const filtered = await filterGitIgnored(matched, cds);
  for (const p of filtered) {
    const c = canonical(p);
    if (!set.has(c)) set.set(c, p);
  }

  return [...set.values()];
}

module.exports = { collectWorkspacePackageJsons };
